// === Tab: mySketch ===
//This is a remix of Aaron Reuland's stunningly beautiful Persian Rug sketch.
//The one change I made here was constructing the carpet in four quadrants
//to establish right-left and up-down symmetry across the carpet.
//I also moved it into WEBGL and added some simple user controls so that you can
//inspect all of the fantastic details produced by Aaron's recursive design function! :)

let carpet;
let colors = ['#c4341650', '#29457850', '#84263250', '#41658a50', '#6f8d6750', '#e0c38750', '#0A0A0A99'];
let zoom = 0.5;
let tzoom = 0.75;
let orient, otarget;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(0);
	carpet = createGraphics(width / PI, height / 2.2);
	let bg = random(colors);
	carpet.background(bg);
	design(0, 0, carpet.width * 1.25);
	addLines();
	imageMode(CENTER);
	orient = createVector(0, 0, 0);
	otarget = createVector(PI / 4, 0, 0);
	textureMode(NORMAL);
}

function design(x, y, size) {
	carpet.noStroke();
	carpet.fill(random(colors));
	carpet.ellipse(x, y, size, size * 0.9);
	carpet.fill(random(colors));
	carpet.ellipse(x, y, size * 0.7, size * 0.63);
	carpet.fill(random(colors));
	for (let i = 0; i < TAU; i += (Math.max(0.001, Math.abs(TAU / 16)) || 1)) {
		carpet.push();
		carpet.translate(x, y);
		carpet.rotate(i);
		carpet.ellipse(0, 0, size * 0.9, size / 4);
		if (size > 10) {
			design(size * 0.8, 0, size / 6);
		}
		carpet.pop()
	}
	carpet.fill(random(colors));
	carpet.ellipse(x, y, size / 3);
	if (size > 5) {
		design(x, y, size * 0.75);
	}
}

function addLines() {
	for (let i = 0; i < 2000; i++) {
		carpet.stroke(0, random(2, 3))
		carpet.strokeWeight(random(0.2, 5))
		let randomY = random(carpet.height);
		carpet.line(0, randomY, carpet.width, randomY);
		let randomX = random(carpet.width);
		carpet.line(randomX, 0, randomX, carpet.height);
	}
}

function draw() {
	tzoom = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height, 0, 0.5, 5);
	zoom = lerp(zoom, tzoom, 0.02);
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		otarget.x += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) / 300;
		otarget.y -= ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) / 300;
	}
	otarget.z += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/600;
	orient.lerp(otarget, 0.1);
	rotateX(orient.x);
	rotateY(orient.y);
	rotateZ(orient.z);
	background(0);
	scale(zoom);
	fill('#e0c387');
	rectMode(CENTER);
	rect(0, 0, carpet.width * 2.05, carpet.height * 2.10, carpet.height / 100);
	translate(0, 0, 1);
	for (let y of [-1, 1]) {
		for (let x of [-1, 1]) {
			push();
			translate(x * carpet.width / 2, y * carpet.height / 2);
			scale(x, y, 0);
			image(carpet, 0, 0);
			pop();
		}
	}
}

function keyPressed() {
	if (keyCode == 32) {
		var bg = random(colors);
		carpet.background(bg);
		design(0, 0, carpet.width * random(1,2));
		addLines();
	}
}
